import NavigationPanel, { type WalkingRoute } from './NavigationPanel';
import { type ComponentRef, useEffect, useRef, useState } from 'react';
import {
  CircleMarker,
  GeoJSON,
  MapContainer,
  Polyline,
  TileLayer,
  Tooltip,
  useMap,
} from 'react-leaflet';

// Generated by OpenAI Codex on 2026-11-03: labels support flat and nested OSM tags.
function onEachFeature(feature: any, layer: any) {
  const properties = feature.properties ?? {};
  const tags = properties.tags ?? properties;
  const text = (value: unknown) => (typeof value === 'string' ? value.trim() : '');
  const kind = ['amenity', 'shop', 'tourism', 'leisure', 'building']
    .map((key) => text(tags[key]))
    .find((value) => value && value !== 'yes');
  const name =
    text(tags.name) ||
    text(tags['name:en']) ||
    text(tags.brand) ||
    `Unnamed ${kind ? kind.replaceAll('_', ' ') : 'location'}`;

  // Leaflet interprets strings as HTML; DOM textContent keeps OSM values safe.
  const label = document.createElement('span');
  label.textContent = name;
  layer.bindTooltip(label, { direction: 'top' });

  const popupContent = document.createElement('div');
  const heading = document.createElement('strong');
  heading.textContent = name;
  popupContent.appendChild(heading);
  const identifier = document.createElement('div');
  identifier.textContent = `Feature: ${feature.id ?? properties.id ?? 'unknown'}`;
  popupContent.appendChild(identifier);
  for (const [key, value] of Object.entries(tags)) {
    const row = document.createElement('div');
    row.textContent = `${key}: ${String(value)}`;
    popupContent.appendChild(row);
  }
  layer.bindPopup(popupContent);
  let loaded = false;
  layer.on('popupopen', async () => {
    if (loaded) return;
    const api = process.env.EXPO_PUBLIC_API_URL || 'http://localhost:8000/api';
    try {
      const response = await fetch(`${api}/map/features/${feature.id}`, { credentials: 'include' });
      if (!response.ok) throw new Error('Could not load feature details');
      const detail = await response.json();
      const content = document.createElement('div');
      const title = document.createElement('strong');
      title.textContent = detail.tags.name || name;
      content.appendChild(title);
      for (const [key, value] of Object.entries(detail.tags)) {
        const row = document.createElement('div');
        row.textContent = `${key}: ${String(value)}`;
        content.appendChild(row);
      }
      if (detail.building_id) {
        const row = document.createElement('div');
        row.textContent = `Building ID: ${detail.building_id}`;
        content.appendChild(row);
      }
      const id = document.createElement('div');
      id.textContent = `Feature: ${detail.id}`;
      content.appendChild(id);
      layer.setPopupContent(content);
      loaded = true;
    } catch {
      const error = document.createElement('div');
      error.textContent = 'Details unavailable. Close and reopen to retry.';
      layer.setPopupContent(error);
    }
  });
}

// A stable component preserves the map layer across parent renders.
function MapFeatures({ geoJson }: { geoJson: any }) {
  const map = useMap();
  const layerRef = useRef<ComponentRef<typeof GeoJSON>>(null);

  useEffect(() => {
    if (geoJson.features?.length && layerRef.current) {
      const bounds = layerRef.current.getBounds();
      if (bounds.isValid()) {
        map.fitBounds(bounds, { padding: [30, 30] });
      }
    }
  }, [geoJson, map]);

  return (
    <GeoJSON
      ref={layerRef}
      data={geoJson}
      onEachFeature={onEachFeature}
      style={{ color: '#2980b9', weight: 3, opacity: 0.8 }}
    />
  );
}

function MapResize() {
  const map = useMap();
  useEffect(() => {
    const observer = new ResizeObserver(() => map.invalidateSize({ pan: false }));
    observer.observe(map.getContainer());
    return () => observer.disconnect();
  }, [map]);
  return null;
}

function RouteLayer({ route }: { route: WalkingRoute }) {
  const map = useMap();
  const points = route.geometry.coordinates.map(([lon, lat]) => [lat, lon] as [number, number]);
  useEffect(() => {
    map.invalidateSize({ pan: false });
    map.fitBounds(
      route.geometry.coordinates.map(([lon, lat]) => [lat, lon] as [number, number]),
      { padding: [40, 40], maxZoom: 18 },
    );
  }, [map, route]);
  return (
    <>
      <Polyline
        positions={points}
        pathOptions={{ color: '#ffffff', weight: 9 }}
        interactive={false}
      />
      <Polyline
        positions={points}
        pathOptions={{ color: '#7327db', weight: 5 }}
        interactive={false}
      />
      <CircleMarker
        center={points[0]}
        radius={8}
        pathOptions={{ color: '#157846', fillOpacity: 1 }}
      >
        <Tooltip permanent>Start</Tooltip>
      </CircleMarker>
      <CircleMarker
        center={points[points.length - 1]}
        radius={8}
        pathOptions={{ color: '#a52a30', fillOpacity: 1 }}
      >
        <Tooltip permanent>Destination</Tooltip>
      </CircleMarker>
    </>
  );
}

export default function MapCanvas({ geoJson }: { geoJson: any }) {
  const [route, setRoute] = useState<WalkingRoute | null>(null);
  return (
    <div
      style={{
        flex: 1,
        width: '100%',
        height: '100%',
        display: 'flex',
        flexDirection: 'column',
        minHeight: 0,
      }}
    >
      <NavigationPanel onRoute={setRoute} />
      <MapContainer
        center={[43.5853, -84.7732]}
        zoom={13}
        style={{ flex: 1, minHeight: 200, width: '100%' }}
      >
        <MapResize />
        <TileLayer
          attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        />
        {geoJson && <MapFeatures key={JSON.stringify(geoJson)} geoJson={geoJson} />}
        {route && <RouteLayer route={route} />}
      </MapContainer>
    </div>
  );
}
